<template>
  <div class="performance_record">
    <title-line :title="title" />
  </div>
</template>
<script>
import TitleLine from '../modules/TitleLine'
export default {
  components: {
    TitleLine
  },
  data() {
    return {
      title: ''
    }
  },
  mounted() {
    this.title = this.$route.query.queryType === 1 ? '直属业绩' : '代理业绩'
  }
}
</script>
<style lang="less">
.performance_record{
    min-height: 100vh;
    width: 100%;
    background: #19223b;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
}
</style>
